def split_words(text):
    """
    This function takes a string as input and processes it based on specific rules.
    It returns a list of words split on whitespace if there are spaces, or a list of words split on commas if there are commas.
    If neither spaces nor commas exist, it counts the number of lower-case letters with odd positions in the alphabet and returns this count.

    Examples:
    process_text("Hello world!") ➞ ["Hello", "world!"]
    process_text("Hello,world!") ➞ ["Hello", "world!"]
    process_text("abcdef") == 3
    """
    # First check for spaces
    if ' ' in text:
        return text.split()

    # Then check for commas
    elif ',' in text:
        return text.split(',')

    # Finally, count odd-positioned lowercase letters
    else:
        return sum(1 for char in text if char.islower() and (ord(char) - ord('a')) % 2 == 1)

