def combine_dicts(dict_a, dict_b, dict_c):
    # Initialize an empty dictionary to store the combined results
    combined_dict = {}

    # Iterate over all keys from the first three dictionaries
    for key in set(dict_a.keys()) | set(dict_b.keys()) | set(dict_c.keys()):
        # Use a generator expression to find the first non-None value among the three dictionaries
        combined_value = next((value for value in (dict_a.get(key), dict_b.get(key), dict_c.get(key)) if value is not None), None)

        # Add the key-value pair to the combined dictionary
        combined_dict[key] = combined_value

    # Return the combined dictionary
    return combined_dict

